namespace casa;
table Ciao { path:string; version:string; }
table Outputs { tool:Ciao (required); }
root_type Outputs;

{ pkgs, inputs, params }:
# CIAO is fixed like the observation in load: the flake by its commit and hash
# (nixSources in tsugumi.json), which fixes CIAO's source, then built once by Nix.
let
  ciao = inputs.sources.ciao.packages.ciao;
in
{
  run = ''
    echo "ciao: ${ciao} (${ciao.name})"
    printf '{"tool": {"path": "%s", "version": "%s"}}' "${ciao}" "${(builtins.parseDrvName ciao.name).version}" > "$TSUGUMI_OUTPUT"
  '';
}

{
  "language": "bash",
  "inputs": [
    {
      "name": "start"
    }
  ]
}

namespace casa;
table Events { path:string; obsid:string; }
table Outputs { events:Events (required); }
root_type Outputs;

{ pkgs, inputs, params }:
# The observation is fixed like a package: fetched once by its hash from the
# HEASARC mirror of the Chandra archive (explicit FTPS), then every run reads
# the same file from the Nix store. Changing obsid, file or hash refetches.
let
  obsid = params.obsid;
  last = builtins.substring (builtins.stringLength obsid - 1) 1 obsid;
  url = "ftp://heasarc.gsfc.nasa.gov/chandra/data/byobsid/${last}/${obsid}/primary/${params.file}";
  raw = pkgs.fetchurl {
    inherit url;
    curlOptsList = [ "--ssl-reqd" ];
    hash = params.hash;
  };
  events = pkgs.runCommand "casa-${obsid}-evt2.fits" { } "gunzip -c ${raw} > $out";
in
{
  run = ''
    echo "source: ${url}"
    echo "hash: ${params.hash}"
    echo "events: ${events} ($(stat -c %s ${events}) bytes)"
    printf '{"events": {"path": "%s", "obsid": "%s"}}' "${events}" "${obsid}" > "$TSUGUMI_OUTPUT"
  '';
}

{
  "language": "bash",
  "inputs": [
    {
      "name": "start"
    }
  ],
  "params": [
    {
      "name": "obsid",
      "type": "string",
      "data": "25628",
      "nix": true
    },
    {
      "name": "file",
      "type": "string",
      "data": "acisf25628N002_evt2.fits.gz",
      "nix": true
    },
    {
      "name": "hash",
      "type": "string",
      "data": "sha256-MYAMIQXv/cwAV6L30N5+XODCrCSYk6NTqpMV+VSDwp4=",
      "nix": true
    }
  ]
}

attribute "tsugumi";
namespace casa;
table BandDir { value:string; }
table Outputs { images:BandDir (required, tsugumi: "directory"); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ps.astropy ];
  };
}

